import { FormEvent, ReactNode, useCallback, useEffect, useMemo, useState } from 'react'
import { api, apiResult, asList, downloadApi, JsonObject, readToken } from './api'
import { ProbeSettingsPanel } from './probe-settings'

type AnyRecord = Record<string, any>

const valueText = (value: unknown, fallback = '') => value === undefined || value === null ? fallback : String(value)
const valueNumber = (value: unknown, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback
const valueBool = (value: unknown, fallback = false) => typeof value === 'boolean' ? value : fallback
const errorText = (error: unknown) => error instanceof Error ? error.message : '操作失败'
const list = <T,>(value: unknown, keys: string[]) => asList<T>(value, keys)

function Icon({ name, size = 18 }: { name: string; size?: number }) {
  const paths: Record<string, string> = {
    refresh: 'M20 6v5h-5M4 18v-5h5m10.5-2A8 8 0 0 0 6 7.5L4 11m16 2-2 3.5A8 8 0 0 1 4.5 14',
    plus: 'M12 5v14M5 12h14', shield: 'M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z',
    bell: 'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-8 13h4',
    database: 'M4 5c0-2 16-2 16 0v14c0 2-16 2-16 0V5Zm0 0c0 2 16 2 16 0M4 12c0 2 16 2 16 0',
    download: 'M12 3v12m-5-5 5 5 5-5M5 21h14', upload: 'M12 15V3m-5 5 5-5 5 5M5 21h14',
    activity: 'M3 12h4l3-8 4 16 3-8h4', terminal: 'm4 6 5 5-5 5m7 0h9',
    copy: 'M8 8h12v12H8V8Zm-4 8V4h12', trash: 'M4 7h16m-10 4v6m4-6v6M9 7l1-3h4l1 3m-9 0 1 14h10l1-14',
    close: 'm6 6 12 12M18 6 6 18', check: 'm5 12 4 4L19 6', key: 'M21 2l-2 2m-7.6 7.6A5 5 0 1 1 4.3 4.5a5 5 0 0 1 7.1 7.1Zm0 0L15 8l2 2 2-2 2 2',
  }
  return <svg className="icon" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d={paths[name] ?? paths.activity}/></svg>
}

function Button({ variant = 'primary', icon, children, ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'secondary' | 'ghost' | 'danger'; icon?: string }) {
  return <button {...props} className={`btn ${variant} ${props.className ?? ''}`}>{icon && <Icon name={icon}/>} {children}</button>
}
function Header({ title, description, actions }: { title: string; description: string; actions?: ReactNode }) {
  return <div className="page-header"><div><h1>{title}</h1><p>{description}</p></div>{actions && <div className="page-actions">{actions}</div>}</div>
}
function Card({ children, className = '' }: { children: ReactNode; className?: string }) { return <section className={`pixel-card ${className}`}>{children}</section> }
function Feedback({ message, error = false }: { message: string; error?: boolean }) { return message ? <div className={`notice ${error ? 'error' : ''}`}>{message}</div> : null }
function Loading() { return <div className="loading"><span className="operation-spinner"/>正在加载…</div> }
function Empty({ title, text }: { title: string; text: string }) { return <div className="empty"><span className="empty-icon"><Icon name="activity" size={24}/></span><strong>{title}</strong><p>{text}</p></div> }
function Modal({ title, description, onClose, children, wide = false }: { title: string; description?: string; onClose: () => void; children: ReactNode; wide?: boolean }) {
  return <div className="modal-backdrop" onMouseDown={(event) => event.target === event.currentTarget && onClose()}><div className={`modal ${wide ? 'modal-wide' : ''}`} role="dialog" aria-modal="true"><div className="modal-head"><div><h2>{title}</h2>{description && <p>{description}</p>}</div><Button variant="ghost" onClick={onClose} aria-label="关闭"><Icon name="close"/></Button></div>{children}</div></div>
}
function Toggle({ label, hint, checked, onChange }: { label: string; hint?: string; checked: boolean; onChange: (value: boolean) => void }) {
  return <label className="setting compact-setting"><div><strong>{label}</strong>{hint && <small>{hint}</small>}</div><input type="checkbox" checked={checked} onChange={(event) => onChange(event.target.checked)}/><span className="switch"/></label>
}
function formatBytes(value: unknown) {
  let bytes = valueNumber(value)
  if (bytes <= 0) return '0 B'
  const units = ['B', 'KB', 'MB', 'GB', 'TB', 'PB']
  let index = 0
  while (bytes >= 1024 && index < units.length - 1) { bytes /= 1024; index += 1 }
  return `${bytes.toFixed(index > 2 ? 2 : 1)} ${units[index]}`
}
function formatDate(value: unknown) {
  if (!value) return '—'
  const date = new Date(String(value))
  return Number.isNaN(date.getTime()) ? String(value) : date.toLocaleString('zh-CN', { hour12: false })
}

export function TrafficOperationsPage() {
  const [summary, setSummary] = useState<AnyRecord>({})
  const [servers, setServers] = useState<AnyRecord[]>([])
  const [users, setUsers] = useState<AnyRecord[]>([])
  const [connections, setConnections] = useState<Record<string, number>>({})
  const [tab, setTab] = useState<'servers' | 'users'>('servers')
  const [loading, setLoading] = useState(true)
  const [feedback, setFeedback] = useState({ message: '', error: false })
  const load = useCallback(async () => {
    setLoading(true); setFeedback({ message: '', error: false })
    const [a, b, c, d] = await Promise.allSettled([
      api<AnyRecord>('/api/traffic/summary'), api<AnyRecord>('/api/admin/traffic'),
      api<AnyRecord>('/api/admin/traffic/users'), api<AnyRecord>('/api/admin/traffic/user-connections'),
    ])
    if (a.status === 'fulfilled') setSummary(a.value)
    if (b.status === 'fulfilled') setServers(list<AnyRecord>(b.value, ['servers']).map((server) => ({ ...server,
      inbounds: list<AnyRecord>(server.inbounds, []).map((row) => ({ ...row, uplink: valueNumber(row.total_uplink) + valueNumber(row.uplink), downlink: valueNumber(row.total_downlink) + valueNumber(row.downlink) })),
      outbounds: list<AnyRecord>(server.outbounds, []).map((row) => ({ ...row, uplink: valueNumber(row.total_uplink) + valueNumber(row.uplink), downlink: valueNumber(row.total_downlink) + valueNumber(row.downlink) })),
    })))
    if (c.status === 'fulfilled') setUsers(list(c.value, ['users']))
    if (d.status === 'fulfilled') setConnections((d.value.connections ?? {}) as Record<string, number>)
    const failed = [a, b, c, d].filter((item) => item.status === 'rejected') as PromiseRejectedResult[]
    if (failed.length === 4) setFeedback({ message: errorText(failed[0].reason), error: true })
    else if (failed.length) setFeedback({ message: `部分统计暂时不可用（${failed.length} 项）`, error: true })
    setLoading(false)
  }, [])
  useEffect(() => { void load() }, [load])
  const metrics = summary.metrics ?? {}
  const history = Array.isArray(summary.history) ? summary.history as AnyRecord[] : []
  const max = Math.max(1, ...history.map((item) => valueNumber(item.used_gb)))
  const resetUser = async (username: string) => {
    if (!window.confirm(`确认把 ${username} 的当前流量周期重置为 0？`)) return
    try { await api(`/api/admin/traffic/users/${encodeURIComponent(username)}`, { method: 'DELETE' }); setFeedback({ message: `${username} 的流量周期已重置。`, error: false }); await load() }
    catch (reason) { setFeedback({ message: errorText(reason), error: true }) }
  }
  return <><Header title="流量中心" description="统一查看服务器、节点和用户的实时与周期流量" actions={<Button variant="secondary" icon="refresh" onClick={() => void load()}>刷新统计</Button>}/><Feedback {...feedback}/><div className="metric-grid"><Card className="metric"><span className="metric-icon peach"><Icon name="activity"/></span><div><p>总额度</p><strong>{valueNumber(metrics.total_limit_gb).toFixed(2)} GB</strong><small>所有计入统计的限额</small></div></Card><Card className="metric"><span className="metric-icon purple"><Icon name="activity"/></span><div><p>已使用</p><strong>{valueNumber(metrics.total_used_gb).toFixed(2)} GB</strong><small>不限量另计 {valueNumber(metrics.unlimited_used_gb).toFixed(2)} GB</small></div></Card><Card className="metric"><span className="metric-icon green"><Icon name="activity"/></span><div><p>剩余</p><strong>{valueNumber(metrics.total_remaining_gb).toFixed(2)} GB</strong><small>当前统计周期</small></div></Card><Card className="metric"><span className="metric-icon blue"><Icon name="activity"/></span><div><p>使用率</p><strong>{valueNumber(metrics.usage_percentage).toFixed(1)}%</strong><small>后端统一计费口径</small></div></Card></div><div className="dashboard-grid"><Card className="traffic-card"><div className="card-head"><div><h2>30 日趋势</h2><p>空采样保留断点，不伪装成 0 流量</p></div></div>{history.length ? <div className="chart extended-chart">{history.map((item, index) => <div className={`bar-wrap ${item.used_gb === null ? 'missing' : ''}`} key={`${item.date}-${index}`} title={item.used_gb === null ? `${item.date}: 无采样` : `${item.date}: ${valueNumber(item.used_gb).toFixed(2)} GB`}><i style={{ height: item.used_gb === null ? '2px' : `${Math.max(4, valueNumber(item.used_gb) / max * 100)}%` }}/><small>{valueText(item.date).slice(5)}</small></div>)}</div> : <Empty title="暂无趋势" text="采集器产生首条每日快照后会显示在这里。"/>}</Card><Card><div className="card-head"><div><h2>统计口径</h2><p>数值均由后端结算，避免前端重复计费</p></div></div><div className="info-stack"><div><strong>限流服务器</strong><span>已用 / 限额参与使用率</span></div><div><strong>不限流服务器</strong><span>单独展示，不污染分母</span></div><div><strong>普通用户</strong><span>套餐倍率、覆写限额与外部订阅合并</span></div><div><strong>缺失采样</strong><span>趋势图显示断点，不按零流量处理</span></div></div></Card></div><Card className="table-card"><div className="table-toolbar"><div className="tabs"><button className={tab === 'servers' ? 'active' : ''} onClick={() => setTab('servers')}>服务器 {servers.length}</button><button className={tab === 'users' ? 'active' : ''} onClick={() => setTab('users')}>用户 {users.length}</button></div></div>{loading ? <Loading/> : tab === 'servers' ? (servers.length ? <div className="responsive-table"><table><thead><tr><th>服务器</th><th>入站</th><th>出站</th><th>用户</th><th>总流量</th></tr></thead><tbody>{servers.map((server) => { const inbound = list<AnyRecord>(server.inbounds, []); const outbound = list<AnyRecord>(server.outbounds, []); const people = list<AnyRecord>(server.users, []); const bytes = [...inbound, ...outbound].reduce((sum, row) => sum + valueNumber(row.uplink) + valueNumber(row.downlink), 0); return <tr key={server.server_id}><td><strong>{server.server_name || `#${server.server_id}`}</strong></td><td>{inbound.length}</td><td>{outbound.length}</td><td>{people.length}</td><td>{formatBytes(bytes)}</td></tr>})}</tbody></table></div> : <Empty title="暂无服务器流量" text="Agent 上报统计后会显示。"/>) : (users.length ? <div className="responsive-table"><table><thead><tr><th>用户</th><th>周期上行</th><th>周期下行</th><th>累计</th><th>连接数</th><th className="right">操作</th></tr></thead><tbody>{users.map((user) => <tr key={user.username}><td><strong>{user.username}</strong></td><td>{formatBytes(user.cycle_uplink)}</td><td>{formatBytes(user.cycle_downlink)}</td><td>{formatBytes(valueNumber(user.total_uplink) + valueNumber(user.total_downlink))}</td><td>{connections[user.username] ?? 0}</td><td className="right"><Button variant="ghost" onClick={() => void resetUser(user.username)}>重置周期</Button></td></tr>)}</tbody></table></div> : <Empty title="暂无用户流量" text="用户节点开始传输后会显示。"/>)}</Card></>
}

type Certificate = AnyRecord & { id: number; domain: string }
type DNSProvider = AnyRecord & { id: number; name: string }

export function CertificatesOperationsPage() {
  const [certificates, setCertificates] = useState<Certificate[]>([])
  const [providers, setProviders] = useState<DNSProvider[]>([])
  const [master, setMaster] = useState<AnyRecord>({})
  const [tab, setTab] = useState<'certificates' | 'providers' | 'master'>('certificates')
  const [editing, setEditing] = useState<'certificate' | 'provider' | 'upload' | null>(null)
  const [deploying, setDeploying] = useState<Certificate | null>(null)
  const [loading, setLoading] = useState(true)
  const [feedback, setFeedback] = useState({ message: '', error: false })
  const load = useCallback(async () => {
    setLoading(true)
    const [a, b, d] = await Promise.allSettled([api<AnyRecord>('/api/admin/certificates'), api<AnyRecord>('/api/admin/dns-providers'), api<AnyRecord>('/api/admin/master-cert-status')])
    if (a.status === 'fulfilled') setCertificates(list(a.value, ['certificates']))
    if (b.status === 'fulfilled') setProviders(list(b.value, ['providers', 'dns_providers']))
    if (d.status === 'fulfilled') setMaster(d.value)
    setLoading(false)
  }, [])
  useEffect(() => { void load() }, [load])
  const run = async (message: string, action: () => Promise<unknown>) => { try { await action(); setFeedback({ message, error: false }); await load() } catch (reason) { setFeedback({ message: errorText(reason), error: true }) } }
  const removeCertificate = (item: Certificate) => { if (window.confirm(`仅删除 ${item.domain} 的证书数据库记录？已写入磁盘或下发到服务器的文件不会被删除。`)) void run('证书记录已删除；已部署文件保持不变。', () => api('/api/admin/certificates/delete', { method: 'DELETE', body: JSON.stringify({ id: item.id }) })) }
  const removeProvider = (item: DNSProvider) => { if (window.confirm(`删除 DNS 凭据“${item.name}”？依赖它的自动续期和 DDNS 可能会失败。`)) void run('DNS 凭据已删除。', () => api(`/api/admin/dns-providers/${item.id}`, { method: 'DELETE' })) }
  return <><Header title="证书与 DNS" description="由主控签发证书，再按需部署到主控与远程服务器" actions={<><Button variant="secondary" icon="refresh" onClick={() => void load()}>刷新</Button>{tab === 'certificates' && <><Button variant="secondary" icon="upload" onClick={() => setEditing('upload')}>上传证书</Button><Button icon="plus" onClick={() => setEditing('certificate')}>申请证书</Button></>}{tab === 'providers' && <Button icon="plus" onClick={() => setEditing('provider')}>添加 DNS 凭据</Button>}</>}/><Feedback {...feedback}/><Card className="table-card"><div className="table-toolbar"><div className="tabs"><button className={tab === 'certificates' ? 'active' : ''} onClick={() => setTab('certificates')}>证书 {certificates.length}</button><button className={tab === 'providers' ? 'active' : ''} onClick={() => setTab('providers')}>DNS 凭据 {providers.length}</button><button className={tab === 'master' ? 'active' : ''} onClick={() => setTab('master')}>主控 HTTPS</button></div></div>{loading ? <Loading/> : tab === 'certificates' ? (certificates.length ? <div className="responsive-table"><table><thead><tr><th>域名</th><th>签发方式</th><th>部署位置</th><th>有效期</th><th>自动化</th><th>状态</th><th className="right">操作</th></tr></thead><tbody>{certificates.map((item) => <tr key={item.id}><td><strong>{item.domain}</strong><small className="table-sub">{(item.domains ?? []).join(', ')}</small></td><td>{item.provider || item.challenge_mode || 'ACME'}</td><td>{item.remote_server_name || '主控'} · {item.deploy_target || '未部署'}</td><td>{formatDate(item.expiry_date)}</td><td>{item.auto_renew ? '续期' : '手动'} / {item.auto_deploy ? '部署' : '手动'}</td><td><span className={`badge ${item.status === 'valid' || item.status === 'issued' ? 'success' : ''}`}>{item.status || 'unknown'}</span></td><td className="right action-cell"><Button variant="ghost" onClick={() => void run('证书续期请求已提交，请刷新状态确认结果。', () => api('/api/admin/certificates/renew', { method: 'POST', body: JSON.stringify({ id: item.id }) }))}>续期</Button><Button variant="ghost" onClick={() => setDeploying(item)}>部署</Button><Button variant="ghost" icon="download" onClick={() => void downloadApi(`/api/admin/certificates/download?id=${item.id}`)}>下载</Button><Button variant="danger" icon="trash" onClick={() => removeCertificate(item)}>删除</Button></td></tr>)}</tbody></table></div> : <Empty title="暂无证书" text="申请 ACME 证书或上传已有 PEM 材料。"/>) : tab === 'providers' ? (providers.length ? <div className="responsive-table"><table><thead><tr><th>名称</th><th>服务商</th><th>创建时间</th><th className="right">操作</th></tr></thead><tbody>{providers.map((item) => <tr key={item.id}><td><strong>{item.name}</strong></td><td>{item.provider_type}</td><td>{formatDate(item.created_at)}</td><td className="right"><Button variant="danger" icon="trash" onClick={() => removeProvider(item)}>删除</Button></td></tr>)}</tbody></table></div> : <Empty title="暂无 DNS 凭据" text="DNS-01 验证需要先保存服务商 API 凭据。"/>) : <MasterCertificatePanel data={master} certificates={certificates} onRun={run}/>}</Card>{editing === 'certificate' && <CertificateEditor providers={providers} onClose={() => setEditing(null)} onSaved={() => { setEditing(null); setFeedback({ message: '证书任务已创建；签发异步进行，请稍后刷新状态。', error: false }); void load() }}/>} {editing === 'provider' && <DNSProviderEditor onClose={() => setEditing(null)} onSaved={() => { setEditing(null); setFeedback({ message: 'DNS 凭据已保存。', error: false }); void load() }}/>} {editing === 'upload' && <CertificateUpload onClose={() => setEditing(null)} onSaved={() => { setEditing(null); setFeedback({ message: '证书材料已上传。', error: false }); void load() }}/>} {deploying && <CertificateDeploy item={deploying} onClose={() => setDeploying(null)} onSaved={() => { setDeploying(null); setFeedback({ message: '部署请求已提交；请查看系统与 Agent 日志确认各目标结果。', error: false }); void load() }}/>}</>
}

function CertificateDeploy({ item, onClose, onSaved }: { item: Certificate; onClose: () => void; onSaved: () => void }) {
  const [target, setTarget] = useState(valueText(item.deploy_target) === 'none' ? 'both' : valueText(item.deploy_target, 'both'))
  const [certPath, setCertPath] = useState(valueText(item.deploy_cert_path))
  const [keyPath, setKeyPath] = useState(valueText(item.deploy_key_path))
  const [busy, setBusy] = useState(false); const [error, setError] = useState('')
  const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(''); try { await api('/api/admin/certificates/deploy', { method: 'POST', body: JSON.stringify({ id: item.id, deploy_target: target, deploy_cert_path: certPath.trim(), deploy_key_path: keyPath.trim() }) }); onSaved() } catch (reason) { setError(errorText(reason)) } finally { setBusy(false) } }
  return <Modal title={`部署证书 · ${item.domain}`} description="路径会保存到证书记录，并同时尝试部署到主控和所有远程服务器" onClose={onClose}><form className="modal-form" onSubmit={submit}><label><span>部署目标</span><select value={target} onChange={(event) => setTarget(event.target.value)}><option value="nginx">Nginx</option><option value="xray">Xray</option><option value="both">Nginx + Xray</option></select></label><label><span>证书部署路径</span><input required value={certPath} onChange={(event) => setCertPath(event.target.value)} placeholder="/usr/local/nginx/cert/example.pem"/></label><label><span>私钥部署路径</span><input required value={keyPath} onChange={(event) => setKeyPath(event.target.value)} placeholder="/usr/local/nginx/cert/example.key"/></label><Feedback message={error} error/><div className="modal-actions"><Button type="button" variant="secondary" onClick={onClose}>取消</Button><Button type="submit" disabled={busy}>{busy ? '部署中…' : '确认部署'}</Button></div></form></Modal>
}

function CertificateEditor({ providers, onClose, onSaved }: { providers: DNSProvider[]; onClose: () => void; onSaved: () => void }) {
  const [form, setForm] = useState({ domain: '', email: '', remote_server_id: 0, provider: 'letsencrypt', challenge_mode: 'webroot', webroot_path: '/var/www/html', auto_renew: true, dns_provider_id: 0, deploy_target: 'none', deploy_cert_path: '', deploy_key_path: '', auto_deploy: false, include_root_domain: false })
  const [busy, setBusy] = useState(false); const [error, setError] = useState('')
  const set = (key: string, value: unknown) => setForm((old) => ({ ...old, [key]: value }))
  const submit = async (event: FormEvent) => { event.preventDefault(); setError(''); if (form.challenge_mode === 'dns' && !form.dns_provider_id) { setError('DNS-01 验证必须选择一组有效的 DNS 凭据。'); return } setBusy(true); try { await api('/api/admin/certificates/create', { method: 'POST', body: JSON.stringify(form) }); onSaved() } catch (reason) { setError(errorText(reason)) } finally { setBusy(false) } }
  return <Modal title="申请证书" description="ACME 只在主控本机签发；部署时会再安全下发到远程 Agent" onClose={onClose} wide><form className="modal-form" onSubmit={submit}><div className="field-row"><label><span>域名</span><input required value={form.domain} onChange={(event) => set('domain', event.target.value.trim())} placeholder="example.com 或 *.example.com"/></label><label><span>ACME 邮箱</span><input required type="email" value={form.email} onChange={(event) => set('email', event.target.value)}/></label></div><div className="field-row"><label><span>签发机构</span><select value="letsencrypt" disabled><option value="letsencrypt">Let's Encrypt</option></select></label><label><span>验证方式</span><select value={form.challenge_mode} onChange={(event) => set('challenge_mode', event.target.value)}><option value="webroot">网站根目录</option><option value="dns">域名系统 DNS-01</option><option value="standalone">独立 HTTP-01</option></select></label></div>{form.challenge_mode === 'dns' ? <label><span>DNS 凭据</span><select required value={form.dns_provider_id} onChange={(event) => set('dns_provider_id', Number(event.target.value))}><option value="0">请选择</option>{providers.map((item) => <option key={item.id} value={item.id}>{item.name} · {item.provider_type}</option>)}</select></label> : form.challenge_mode === 'webroot' && <label><span>Webroot 路径</span><input required value={form.webroot_path} onChange={(event) => set('webroot_path', event.target.value)}/></label>}<label><span>签发位置</span><input value="主控本机（远程 Agent 不具备 ACME 签发能力）" disabled/></label><label><span>部署目标</span><select value={form.deploy_target} onChange={(event) => { const target = event.target.value; setForm((old) => ({ ...old, deploy_target: target, auto_deploy: target === 'none' ? false : old.auto_deploy })) }}><option value="none">仅保存</option><option value="nginx">Nginx</option><option value="xray">Xray</option><option value="both">Nginx + Xray</option></select></label>{form.deploy_target !== 'none' && <div className="field-row"><label><span>证书部署路径</span><input required value={form.deploy_cert_path} onChange={(event) => set('deploy_cert_path', event.target.value)} placeholder="/usr/local/nginx/cert/example.pem"/></label><label><span>私钥部署路径</span><input required value={form.deploy_key_path} onChange={(event) => set('deploy_key_path', event.target.value)} placeholder="/usr/local/nginx/cert/example.key"/></label></div>}<div className="setting-list"><Toggle label="自动续期" checked={form.auto_renew} onChange={(value) => set('auto_renew', value)}/>{form.deploy_target !== 'none' && <Toggle label="续期后自动部署" hint="会同步尝试主控和所有远程服务器" checked={form.auto_deploy} onChange={(value) => set('auto_deploy', value)}/>} {form.challenge_mode === 'dns' && form.domain.startsWith('*.') && <Toggle label="通配符同时包含根域" checked={form.include_root_domain} onChange={(value) => set('include_root_domain', value)}/>}</div><Feedback message={error} error/><div className="modal-actions"><Button type="button" variant="secondary" onClick={onClose}>取消</Button><Button type="submit" disabled={busy}>{busy ? '提交中…' : '开始申请'}</Button></div></form></Modal>
}

function DNSProviderEditor({ onClose, onSaved }: { onClose: () => void; onSaved: () => void }) {
  const [name, setName] = useState(''); const [provider, setProvider] = useState('cloudflare'); const [credentials, setCredentials] = useState('{\n  "CF_DNS_API_TOKEN": ""\n}')
  const [busy, setBusy] = useState(false); const [error, setError] = useState('')
  const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(''); try { JSON.parse(credentials); await api('/api/admin/dns-providers/create', { method: 'POST', body: JSON.stringify({ name, provider_type: provider, credentials }) }); onSaved() } catch (reason) { setError(reason instanceof SyntaxError ? '凭据必须是有效 JSON。' : errorText(reason)) } finally { setBusy(false) } }
  const presets: Record<string, string> = { cloudflare: '{\n  "CF_DNS_API_TOKEN": ""\n}', alidns: '{\n  "ALICLOUD_ACCESS_KEY": "",\n  "ALICLOUD_SECRET_KEY": ""\n}', dnspod: '{\n  "DNSPOD_API_KEY": ""\n}', tencentcloud: '{\n  "TENCENTCLOUD_SECRET_ID": "",\n  "TENCENTCLOUD_SECRET_KEY": ""\n}', namesilo: '{\n  "NAMESILO_API_KEY": ""\n}', godaddy: '{\n  "GODADDY_API_KEY": "",\n  "GODADDY_API_SECRET": ""\n}' }
  return <Modal title="添加 DNS 凭据" description="凭据键必须保持界面给出的大小写；材料仅提交给当前主控，保存后不会回显" onClose={onClose}><form className="modal-form" onSubmit={submit}><label><span>显示名称</span><input required value={name} onChange={(event) => setName(event.target.value)} placeholder="Cloudflare 主账号"/></label><label><span>服务商</span><select value={provider} onChange={(event) => { setProvider(event.target.value); setCredentials(presets[event.target.value] ?? '{}') }}><option value="cloudflare">Cloudflare</option><option value="alidns">AliDNS</option><option value="dnspod">DNSPod</option><option value="tencentcloud">腾讯云 DNS</option><option value="namesilo">NameSilo</option><option value="godaddy">GoDaddy</option></select></label><label><span>凭据 JSON</span><textarea className="code-area" rows={7} value={credentials} onChange={(event) => setCredentials(event.target.value)} spellCheck={false}/></label><Feedback message={error} error/><div className="modal-actions"><Button type="button" variant="secondary" onClick={onClose}>取消</Button><Button type="submit" disabled={busy}>{busy ? '保存中…' : '保存凭据'}</Button></div></form></Modal>
}

function CertificateUpload({ onClose, onSaved }: { onClose: () => void; onSaved: () => void }) {
  const [domain, setDomain] = useState(''); const [cert, setCert] = useState(''); const [key, setKey] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState('')
  const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(''); try { await api('/api/admin/certificates/upload', { method: 'POST', body: JSON.stringify({ domain, cert_pem: cert, key_pem: key }) }); onSaved() } catch (reason) { setError(errorText(reason)) } finally { setBusy(false) } }
  return <Modal title="上传证书" description="PEM 私钥只发送到当前主控并写入受保护的证书存储" onClose={onClose} wide><form className="modal-form" onSubmit={submit}><label><span>域名</span><input required value={domain} onChange={(event) => setDomain(event.target.value)}/></label><div className="field-row"><label><span>证书链 PEM</span><textarea required className="code-area" rows={12} value={cert} onChange={(event) => setCert(event.target.value)} spellCheck={false}/></label><label><span>私钥 PEM</span><textarea required className="code-area" rows={12} value={key} onChange={(event) => setKey(event.target.value)} spellCheck={false}/></label></div><Feedback message={error} error/><div className="modal-actions"><Button type="button" variant="secondary" onClick={onClose}>取消</Button><Button type="submit" disabled={busy}>{busy ? '上传中…' : '上传证书'}</Button></div></form></Modal>
}

function MasterCertificatePanel({ data, certificates, onRun }: { data: AnyRecord; certificates: Certificate[]; onRun: (message: string, task: () => Promise<unknown>) => Promise<void> }) {
  const [id, setID] = useState(0); const [domain, setDomain] = useState(valueText(data.domain))
  useEffect(() => { setDomain((current) => current || valueText(data.domain)) }, [data.domain])
  const selectCertificate = (certificateID: number) => {
    setID(certificateID)
    const certificate = certificates.find((item) => Number(item.id) === certificateID)
    const names = certificate ? [...(Array.isArray(certificate.domains) ? certificate.domains : []), certificate.domain].map((name) => valueText(name)) : []
    const exactName = names.find((name) => name && !name.startsWith('*.'))
    if (!domain && exactName) setDomain(exactName)
  }
  const payload = () => JSON.stringify({ certificate_id: id, domain })
  const enableHTTPS = (endpoint: string, message: string) => { if (!window.confirm(`将为 ${domain} 安装所选证书、改写 Nginx 配置，把主控 URL 切换为 HTTPS，并可能重载或重启服务。确认继续？`)) return; void onRun(message, () => api(endpoint, { method: 'POST', body: payload() })) }
  return <div className="master-cert"><div className="metric-grid compact-metrics"><div><small>HTTPS</small><strong>{data.enabled || data.https_enabled ? '已启用' : '未启用'}</strong></div><div><small>当前域名</small><strong>{data.domain || '—'}</strong></div><div><small>证书状态</small><strong>{data.https_enabled ? '已部署' : data.pending ? '待部署' : '未部署'}</strong></div></div><div className="stack-form narrow-form"><label><span>选择有效证书</span><select value={id} onChange={(event) => selectCertificate(Number(event.target.value))}><option value="0">请选择</option>{certificates.map((item) => <option value={item.id} key={item.id}>{item.domain}</option>)}</select></label><label><span>主控域名</span><input value={domain} onChange={(event) => setDomain(event.target.value)} placeholder="panel.example.com"/></label><div className="action-strip"><Button variant="secondary" disabled={!id || !domain} onClick={() => enableHTTPS('/api/admin/deploy-master-cert', '证书已部署，主控 HTTPS 已启用。')}>快速部署并启用 HTTPS</Button><Button disabled={!id || !domain} onClick={() => enableHTTPS('/api/admin/enable-https', '完整 HTTPS 配置已部署。')}>完整配置并启用 HTTPS</Button></div><div className="form-note">两项操作都会切换主控 URL；“完整配置”还会写入受管 Nginx 主模板与回落配置。通配符证书请填写其覆盖的具体子域名。</div></div></div>
}

export function NotificationsOperationsPage() {
  const [tab, setTab] = useState<'notifications' | 'announcements' | 'bot'>('notifications')
  const [config, setConfig] = useState<AnyRecord>({})
  const [announcements, setAnnouncements] = useState<AnyRecord[]>([])
  const [announcementNodes, setAnnouncementNodes] = useState<AnyRecord[]>([])
  const [bot, setBot] = useState<AnyRecord>({ enabled: false, bot_token: '', admin_tg_ids: [] })
  const [draft, setDraft] = useState({ type: 'general', title: '', body: '', node_id: 0, expires_minutes: 0, via_bot: false, via_miniapp: true })
  const [preview, setPreview] = useState('')
  const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(false)
  const [notifyLoaded, setNotifyLoaded] = useState(false); const [botLoaded, setBotLoaded] = useState(false)
  const [feedback, setFeedback] = useState({ message: '', error: false })
  const load = useCallback(async () => {
    setLoading(true); setNotifyLoaded(false); setBotLoaded(false); setFeedback({ message: '', error: false })
    const [a, b, c, d] = await Promise.allSettled([api<AnyRecord>('/api/admin/notify-config'), api<AnyRecord>('/api/admin/announcements'), api<AnyRecord>('/api/admin/system-settings/tgbot'), api<AnyRecord>('/api/admin/nodes')])
    if (a.status === 'fulfilled') { setConfig(a.value); setNotifyLoaded(true) }
    if (b.status === 'fulfilled') setAnnouncements(list(b.value, ['announcements']))
    if (c.status === 'fulfilled') { setBot(c.value); setBotLoaded(true) }
    if (d.status === 'fulfilled') setAnnouncementNodes(list(d.value, ['nodes']))
    const failed = [a, b, c, d].filter((item) => item.status === 'rejected') as PromiseRejectedResult[]
    if (failed.length) setFeedback({ message: `有 ${failed.length} 组配置读取失败；对应保存操作已锁定，请刷新重试。`, error: true })
    setLoading(false)
  }, [])
  useEffect(() => { void load() }, [load])
  const set = (key: string, value: unknown) => setConfig((old) => ({ ...old, [key]: value }))
  const save = async () => { if (!notifyLoaded) { setFeedback({ message: '通知策略尚未完整载入，已阻止保存。请刷新后重试。', error: true }); return } setBusy(true); try { await api('/api/admin/notify-config', { method: 'PUT', body: JSON.stringify(config) }); setFeedback({ message: '通知策略已保存并热更新。', error: false }); await load() } catch (reason) { setFeedback({ message: errorText(reason), error: true }) } finally { setBusy(false) } }
  const test = async () => { setBusy(true); try { await api('/api/admin/notify-config/test', { method: 'POST', body: '{}' }); setFeedback({ message: '测试消息已发送。', error: false }) } catch (reason) { setFeedback({ message: errorText(reason), error: true }) } finally { setBusy(false) } }
  const showPreview = async () => { try { const value = await api<AnyRecord>('/api/admin/notify-config/preview', { method: 'POST', body: JSON.stringify({ template: valueText(config.notify_daily_traffic_template || config.notify_daily_traffic_template_default) }) }); setPreview(valueText(value.preview)) } catch (reason) { setFeedback({ message: errorText(reason), error: true }) } }
  const publish = async (event: FormEvent) => { event.preventDefault(); const isNodeAnnouncement = draft.type === 'node_blocked' || draft.type === 'node_recovered'; if (isNodeAnnouncement && !draft.node_id) { setFeedback({ message: '节点类公告必须选择节点。', error: true }); return } setBusy(true); try { await api('/api/admin/announcements', { method: 'POST', body: JSON.stringify({ ...draft, node_id: isNodeAnnouncement ? draft.node_id : 0 }) }); setDraft({ type: 'general', title: '', body: '', node_id: 0, expires_minutes: 0, via_bot: false, via_miniapp: true }); setFeedback({ message: '公告已发布。', error: false }); await load() } catch (reason) { setFeedback({ message: errorText(reason), error: true }) } finally { setBusy(false) } }
  const remove = async (id: number) => { if (!window.confirm('删除这条公告？')) return; try { await api(`/api/admin/announcements?id=${id}`, { method: 'DELETE' }); setFeedback({ message: '公告已删除。', error: false }); await load() } catch (reason) { setFeedback({ message: errorText(reason), error: true }) } }
  const saveBot = async () => { if (!botLoaded) { setFeedback({ message: 'Bot 配置尚未完整载入，已阻止保存。请刷新后重试。', error: true }); return } setBusy(true); try { await api('/api/admin/system-settings/tgbot', { method: 'PUT', body: JSON.stringify({ enabled: valueBool(bot.enabled), bot_token: valueText(bot.bot_token), admin_tg_ids: Array.isArray(bot.admin_tg_ids) ? bot.admin_tg_ids : [], webapp_dev_preview: valueBool(bot.webapp_dev_preview) }) }); setFeedback({ message: 'Telegram Bot 配置已保存，服务已重载。', error: false }); await load() } catch (reason) { setFeedback({ message: errorText(reason), error: true }) } finally { setBusy(false) } }
  const events = [
    ['notify_login', '登录成功'], ['notify_subscribe_fetch', '订阅获取'], ['notify_daily_traffic', '每日流量汇总'], ['notify_traffic_threshold', '通用流量阈值'],
    ['notify_server_offline', '服务器离线'], ['notify_server_online', '服务器恢复'],
    ['notify_traffic_threshold_80', '流量达到 80%'], ['notify_over_limit', '超出流量限额'], ['notify_package_expiring', '套餐即将到期'], ['notify_package_expired', '套餐已到期'],
    ['notify_user_registered', '新用户注册'], ['notify_telegram_bound', 'Telegram 绑定'], ['notify_cert_result', '证书签发结果'], ['notify_server_renewal', '服务器续费'],
    ['notify_agent_long_offline', 'Agent 长时间离线'], ['notify_device_limit_exceeded', '设备数超限'], ['notify_ip_ban', 'IP 封禁'], ['notify_probe_quality', '探针质量异常'],
  ]
  return <><Header title="通知与公告" description="集中管理 Telegram 通知、站内横幅和内置 Bot" actions={<Button variant="secondary" icon="refresh" onClick={() => void load()}>刷新</Button>}/><Feedback {...feedback}/><Card className="table-card"><div className="table-toolbar"><div className="tabs"><button className={tab === 'notifications' ? 'active' : ''} onClick={() => setTab('notifications')}>通知策略</button><button className={tab === 'announcements' ? 'active' : ''} onClick={() => setTab('announcements')}>公告 {announcements.length}</button><button className={tab === 'bot' ? 'active' : ''} onClick={() => setTab('bot')}>内置 Bot</button></div></div>{loading ? <Loading/> : tab === 'notifications' ? <div className="settings-form extended-settings"><div className="settings-section-head"><div><h2>Telegram 通知通道</h2><p>Bot Token 已配置时会以掩码返回，留着掩码保存不会覆盖密钥。</p></div><Toggle label="启用全局通知" checked={valueBool(config.notify_enabled)} onChange={(value) => set('notify_enabled', value)}/></div><div className="field-row"><label><span>Bot Token</span><input type="password" value={valueText(config.telegram_bot_token)} onChange={(event) => set('telegram_bot_token', event.target.value)} placeholder="123456:ABC…"/></label><label><span>Chat ID</span><input value={valueText(config.telegram_chat_id)} onChange={(event) => set('telegram_chat_id', event.target.value)} placeholder="-100…"/></label></div><div className="toggle-grid">{events.map(([key, label]) => <Toggle key={key} label={label} checked={valueBool(config[key])} onChange={(value) => set(key, value)}/>)}</div><div className="settings-section-head"><div><h2>阈值与节流</h2><p>这些阈值由后端调度器统一执行。</p></div></div><div className="field-grid four"><label><span>每日汇总时间</span><input type="time" value={valueText(config.notify_daily_traffic_time, '09:00')} onChange={(event) => set('notify_daily_traffic_time', event.target.value)}/></label><label><span>流量阈值 %</span><input type="number" min="1" max="100" value={valueNumber(config.notify_traffic_threshold_percent, 80)} onChange={(event) => set('notify_traffic_threshold_percent', Number(event.target.value))}/></label><label><span>离线容忍（秒）</span><input type="number" min="0" value={valueNumber(config.notify_server_tolerance_seconds, 90)} onChange={(event) => set('notify_server_tolerance_seconds', Number(event.target.value))}/></label><label><span>套餐提前提醒（天）</span><input type="number" min="1" value={valueNumber(config.notify_package_expiring_days, 3)} onChange={(event) => set('notify_package_expiring_days', Number(event.target.value))}/></label><label><span>Agent 离线（分钟）</span><input type="number" min="1" value={valueNumber(config.notify_agent_long_offline_minutes, 10)} onChange={(event) => set('notify_agent_long_offline_minutes', Number(event.target.value))}/></label><label><span>抖动阈值 ms</span><input type="number" min="1" value={valueNumber(config.probe_jitter_threshold_ms, 80)} onChange={(event) => set('probe_jitter_threshold_ms', Number(event.target.value))}/></label><label><span>丢包阈值 %</span><input type="number" min="0" max="100" step="0.1" value={valueNumber(config.probe_loss_threshold_pct, 5)} onChange={(event) => set('probe_loss_threshold_pct', Number(event.target.value))}/></label><label><span>探针窗口（分钟）</span><input type="number" min="1" value={valueNumber(config.probe_window_minutes, 10)} onChange={(event) => set('probe_window_minutes', Number(event.target.value))}/></label><label><span>最少采样数</span><input type="number" min="1" value={valueNumber(config.probe_min_samples, 3)} onChange={(event) => set('probe_min_samples', Number(event.target.value))}/></label><label><span>连续触发次数</span><input type="number" min="1" value={valueNumber(config.probe_trigger_consecutive, 2)} onChange={(event) => set('probe_trigger_consecutive', Number(event.target.value))}/></label><label><span>连续恢复次数</span><input type="number" min="1" value={valueNumber(config.probe_recover_consecutive, 2)} onChange={(event) => set('probe_recover_consecutive', Number(event.target.value))}/></label><label><span>冷却时间（分钟）</span><input type="number" min="1" value={valueNumber(config.probe_cooldown_minutes, 30)} onChange={(event) => set('probe_cooldown_minutes', Number(event.target.value))}/></label></div><label><span>每日流量模板</span><textarea rows={10} value={valueText(config.notify_daily_traffic_template || config.notify_daily_traffic_template_default)} onChange={(event) => set('notify_daily_traffic_template', event.target.value)}/></label><div className="form-note">可用占位符以主控当前返回值为准：{Array.isArray(config.notify_daily_traffic_placeholders) ? config.notify_daily_traffic_placeholders.map((item: unknown) => typeof item === 'string' ? item : valueText((item as AnyRecord)?.name)).filter(Boolean).join('、') : '可先使用“预览模板”核对结果'}</div><div className="action-strip"><Button disabled={busy} onClick={() => void save()}>{busy ? '保存中…' : '保存通知策略'}</Button><Button variant="secondary" onClick={() => void test()}>发送测试消息</Button><Button variant="ghost" onClick={() => void showPreview()}>预览模板</Button></div>{preview && <pre className="progress-log preview-message">{preview}</pre>}</div> : tab === 'announcements' ? <div className="split-admin"><form className="stack-form announcement-compose" onSubmit={publish}><h2>发布公告</h2><div className="field-row"><label><span>类型</span><select value={draft.type} onChange={(event) => { const type = event.target.value; setDraft((old) => ({ ...old, type, node_id: type === 'node_blocked' || type === 'node_recovered' ? old.node_id : 0 })) }}><option value="general">一般公告</option><option value="maintenance">维护通知</option><option value="node_blocked">节点异常</option><option value="node_recovered">节点恢复</option><option value="traffic">流量提醒</option></select></label><label><span>有效期（分钟，0 永久）</span><input type="number" min="0" value={draft.expires_minutes} onChange={(event) => setDraft((old) => ({ ...old, expires_minutes: Number(event.target.value) }))}/></label></div>{(draft.type === 'node_blocked' || draft.type === 'node_recovered') && <label><span>关联节点</span><select required value={draft.node_id || ''} onChange={(event) => setDraft((old) => ({ ...old, node_id: Number(event.target.value) }))}><option value="">请选择节点</option>{announcementNodes.map((node) => <option key={node.id} value={node.id}>{node.node_name || node.name || `节点 #${node.id}`}</option>)}</select></label>}<label><span>标题</span><input value={draft.title} onChange={(event) => setDraft((old) => ({ ...old, title: event.target.value }))}/></label><label><span>正文</span><textarea required rows={7} value={draft.body} onChange={(event) => setDraft((old) => ({ ...old, body: event.target.value }))}/></label><div className="field-row"><Toggle label="站内 / Mini App 展示" checked={draft.via_miniapp} onChange={(value) => setDraft((old) => ({ ...old, via_miniapp: value }))}/><Toggle label="通过 Bot 推送" checked={draft.via_bot} onChange={(value) => setDraft((old) => ({ ...old, via_bot: value }))}/></div><Button type="submit" disabled={busy}>发布公告</Button></form><div className="announcement-list"><h2>当前公告</h2>{announcements.length ? announcements.map((item) => <article key={item.id}><div><span className="badge">{item.type}</span><strong>{item.title || '未命名公告'}</strong><p>{item.body}</p><small>{formatDate(item.created_at)} · {item.expires_at ? `至 ${formatDate(item.expires_at)}` : '永久'}</small></div><Button variant="danger" icon="trash" onClick={() => void remove(item.id)}>删除</Button></article>) : <Empty title="没有生效公告" text="发布后会出现在用户界面和 Mini App。"/>}</div></div> : <div className="settings-form extended-settings"><div className="settings-section-head"><div><h2>内置 Telegram Bot</h2><p>保存后会自动重启 Bot；Token 掩码不会覆盖现有值。</p></div><span className={`badge ${bot.running ? 'success' : ''}`}>{bot.running ? '运行中' : '未运行'}</span></div><Toggle label="启用内置 Bot" checked={valueBool(bot.enabled)} onChange={(value) => setBot((old) => ({ ...old, enabled: value }))}/><label><span>Bot Token</span><input type="password" value={valueText(bot.bot_token)} onChange={(event) => setBot((old) => ({ ...old, bot_token: event.target.value }))}/></label><label><span>管理员 Telegram ID（逗号分隔）</span><input value={(Array.isArray(bot.admin_tg_ids) ? bot.admin_tg_ids : []).join(', ')} onChange={(event) => setBot((old) => ({ ...old, admin_tg_ids: event.target.value.split(',').map((part) => Number(part.trim())).filter(Boolean) }))}/></label><Toggle label="Mini App 开发预览" hint="仅调试时开启" checked={valueBool(bot.webapp_dev_preview)} onChange={(value) => setBot((old) => ({ ...old, webapp_dev_preview: value }))}/><div className="info-stack"><div><strong>Bot 地址</strong><span>{bot.bot_url || '保存并连接后生成'}</span></div><div><strong>Mini App</strong><span>/tg-app</span></div></div><Button disabled={busy} onClick={() => void saveBot()}>{busy ? '保存中…' : '保存并重启 Bot'}</Button></div>}</Card></>
}

export function DataOperationsPage() {
  const [tab, setTab] = useState<'database' | 'backup' | 'update' | 'migration'>('database')
  const [status, setStatus] = useState<AnyRecord>({})
  const [database, setDatabase] = useState<AnyRecord>({ driver: 'postgres', host: '127.0.0.1', port: 5432, database: 'mmwx', username: 'mmwx', password: '', ssl_mode: 'disable', max_open_conns: 25, max_idle_conns: 5 })
  const [update, setUpdate] = useState<AnyRecord>({})
  const [channel, setChannel] = useState('stable')
  const [restoreFile, setRestoreFile] = useState<File | null>(null); const [passphrase, setPassphrase] = useState('')
  const [migrationJSON, setMigrationJSON] = useState('{\n  "source": "",\n  "notes": "Use the guided actions below"\n}')
  const [busy, setBusy] = useState(false); const [loading, setLoading] = useState(true)
  const [databaseLoaded, setDatabaseLoaded] = useState(false)
  const [feedback, setFeedback] = useState({ message: '', error: false })
  const load = useCallback(async () => { setLoading(true); setDatabaseLoaded(false); try { const value = await api<AnyRecord>('/api/admin/database/status'); const next = value.status ?? value; const config = next.config && typeof next.config === 'object' ? next.config as AnyRecord : {}; setStatus(next); setDatabase({ driver: valueText(config.driver || next.driver, 'postgres'), path: valueText(config.path), host: valueText(config.host, '127.0.0.1'), port: valueNumber(config.port, 5432), database: valueText(config.database, 'mmwx'), username: valueText(config.username, 'mmwx'), password: '', ssl_mode: valueText(config.ssl_mode, 'disable'), max_open_conns: valueNumber(config.max_open_conns, 25), max_idle_conns: valueNumber(config.max_idle_conns, 5) }); setDatabaseLoaded(true) } catch (reason) { setFeedback({ message: errorText(reason), error: true }) } finally { setLoading(false) } }, [])
  useEffect(() => { void load() }, [load])
  useEffect(() => { setUpdate({}) }, [channel])
  const databasePayload = () => ({ driver: valueText(database.driver), path: valueText(database.path), host: valueText(database.host), port: valueNumber(database.port), database: valueText(database.database), username: valueText(database.username), password: valueText(database.password), ssl_mode: valueText(database.ssl_mode), max_open_conns: valueNumber(database.max_open_conns), max_idle_conns: valueNumber(database.max_idle_conns) })
  const testDatabase = async () => { setBusy(true); try { await api('/api/admin/database/test', { method: 'POST', body: JSON.stringify(databasePayload()) }); setFeedback({ message: '数据库连接与表结构检查成功。', error: false }) } catch (reason) { setFeedback({ message: errorText(reason), error: true }) } finally { setBusy(false) } }
  const migrateDatabase = async () => { if (!databaseLoaded) { setFeedback({ message: '当前数据库配置尚未成功载入，已阻止迁移。请刷新后重试。', error: true }); return } if (!window.confirm('迁移会锁定写入并在成功后重启主控。确认继续？')) return; setBusy(true); try { await api('/api/admin/database/migrate', { method: 'POST', body: JSON.stringify(databasePayload()) }); setFeedback({ message: '数据库迁移完成，主控将重启。', error: false }) } catch (reason) { setFeedback({ message: errorText(reason), error: true }) } finally { setBusy(false) } }
  const restore = async () => { if (!restoreFile || !window.confirm('恢复会覆盖当前数据。请确认已经另存当前备份，继续？')) return; const form = new FormData(); form.set('backup', restoreFile); if (passphrase) form.set('passphrase', passphrase); setBusy(true); try { await api('/api/admin/backup/restore', { method: 'POST', body: form }); setFeedback({ message: '备份已恢复，主控可能正在重启。', error: false }) } catch (reason) { setFeedback({ message: errorText(reason), error: true }) } finally { setBusy(false) } }
  const checkUpdate = async () => { setBusy(true); try { const value = await api<AnyRecord>(`/api/admin/update/check?channel=${channel}`); setUpdate(value); setFeedback({ message: value.has_update ? `发现版本 ${value.latest_version}` : '当前已经是最新版本。', error: false }) } catch (reason) { setFeedback({ message: errorText(reason), error: true }) } finally { setBusy(false) } }
  const applyUpdate = async () => { if (!update.has_update || !window.confirm(`安装 ${update.latest_version} 并重启主控？`)) return; setBusy(true); try { await api(`/api/admin/update/apply?channel=${channel}`, { method: 'POST', body: '{}' }); setFeedback({ message: '更新已安装，主控正在重启。', error: false }) } catch (reason) { setFeedback({ message: errorText(reason), error: true }) } finally { setBusy(false) } }
  const currentConfig = status.config && typeof status.config === 'object' ? status.config as AnyRecord : {}
  const environmentOverride = valueBool(status.environment_override)
  return <><Header title="数据与版本" description="数据库迁移、完整备份恢复、旧系统迁移和主控更新" actions={<Button variant="secondary" icon="refresh" onClick={() => void load()}>刷新状态</Button>}/><Feedback {...feedback}/><Card className="table-card"><div className="table-toolbar"><div className="tabs"><button className={tab === 'database' ? 'active' : ''} onClick={() => setTab('database')}>数据库</button><button className={tab === 'backup' ? 'active' : ''} onClick={() => setTab('backup')}>备份与恢复</button><button className={tab === 'migration' ? 'active' : ''} onClick={() => setTab('migration')}>旧版迁移</button><button className={tab === 'update' ? 'active' : ''} onClick={() => setTab('update')}>版本更新</button></div></div>{loading ? <Loading/> : tab === 'database' ? <div className="settings-form extended-settings"><div className="metric-grid compact-metrics"><div><small>当前驱动</small><strong>{status.driver || 'unknown'}</strong></div><div><small>目标</small><strong>{currentConfig.database || currentConfig.path || '—'}</strong></div><div><small>环境变量托管</small><strong>{environmentOverride ? '是' : '否'}</strong></div><div><small>连接池</small><strong>{valueNumber(status.open_connections)} 打开 / {valueNumber(status.in_use_connections)} 使用中</strong></div></div><div className="settings-section-head"><div><h2>SQLite → PostgreSQL</h2><p>先测试，再迁移；密码留空会在目标未变时沿用当前密码。</p></div></div><div className="field-grid three"><label><span>驱动</span><select value={valueText(database.driver, 'postgres')} onChange={(event) => setDatabase((old) => ({ ...old, driver: event.target.value }))}><option value="postgres">PostgreSQL</option><option value="sqlite">SQLite</option></select></label>{database.driver === 'sqlite' ? <label><span>数据库路径</span><input value={valueText(database.path)} onChange={(event) => setDatabase((old) => ({ ...old, path: event.target.value }))}/></label> : <><label><span>主机</span><input value={valueText(database.host)} onChange={(event) => setDatabase((old) => ({ ...old, host: event.target.value }))}/></label><label><span>端口</span><input type="number" value={valueNumber(database.port, 5432)} onChange={(event) => setDatabase((old) => ({ ...old, port: Number(event.target.value) }))}/></label><label><span>数据库名</span><input value={valueText(database.database)} onChange={(event) => setDatabase((old) => ({ ...old, database: event.target.value }))}/></label><label><span>用户名</span><input value={valueText(database.username)} onChange={(event) => setDatabase((old) => ({ ...old, username: event.target.value }))}/></label><label><span>密码</span><input type="password" value={valueText(database.password)} onChange={(event) => setDatabase((old) => ({ ...old, password: event.target.value }))}/></label><label><span>SSL 模式</span><select value={valueText(database.ssl_mode, 'disable')} onChange={(event) => setDatabase((old) => ({ ...old, ssl_mode: event.target.value }))}><option value="disable">disable</option><option value="prefer">prefer</option><option value="require">require</option><option value="verify-full">verify-full</option></select></label></>}</div><div className="action-strip"><Button variant="secondary" disabled={busy} onClick={() => void testDatabase()}>测试连接</Button><Button disabled={busy || environmentOverride} onClick={() => void migrateDatabase()}>迁移并切换</Button></div>{environmentOverride && <div className="form-note">数据库由 MMWX_DATABASE_* 环境变量管理，页面禁止切换。</div>}</div> : tab === 'backup' ? <div className="split-admin data-split"><section className="action-panel"><span className="round-icon"><Icon name="download"/></span><h2>下载完整备份</h2><p>包含配置、订阅、证书材料和 SQLite 数据。PostgreSQL 数据较大，按需包含 dump。</p><div className="action-strip"><Button onClick={() => void downloadApi('/api/admin/backup/download')}>下载配置备份</Button><Button variant="secondary" onClick={() => void downloadApi('/api/admin/backup/download?include_database=true')}>包含数据库</Button></div></section><section className="action-panel danger-panel"><span className="round-icon"><Icon name="upload"/></span><h2>恢复备份</h2><p>支持当前 ZIP 与旧版加密备份。恢复数据库时主控会自动重启。</p><label><span>备份文件</span><input type="file" accept=".zip,.bak,.mmwx" onChange={(event) => setRestoreFile(event.target.files?.[0] ?? null)}/></label><label><span>旧版备份密码（可选）</span><input type="password" value={passphrase} onChange={(event) => setPassphrase(event.target.value)}/></label><Button variant="danger" disabled={!restoreFile || busy} onClick={() => void restore()}>恢复并覆盖当前数据</Button></section></div> : tab === 'update' ? <div className="settings-form extended-settings"><div className="settings-section-head"><div><h2>主控更新</h2><p>更新前会校验平台包，非容器部署会保留旧二进制。</p></div><span className={`badge ${update.has_update ? '' : 'success'}`}>{update.current_version || '未检查'}</span></div><label className="small-control"><span>更新通道</span><select value={channel} onChange={(event) => setChannel(event.target.value)}><option value="stable">稳定版</option><option value="prerelease">预发布版</option></select></label>{update.latest_version && <div className="update-card"><div><small>最新版本</small><h2>{update.latest_version}</h2><p>{update.release_notes || '无发布说明'}</p></div>{update.release_url && <a href={update.release_url} target="_blank" rel="noreferrer">查看发布页</a>}</div>}<div className="action-strip"><Button variant="secondary" disabled={busy} onClick={() => void checkUpdate()}>检查更新</Button><Button disabled={busy || !update.has_update} onClick={() => void applyUpdate()}>安装并重启</Button></div></div> : <MigrationPanel raw={migrationJSON} setRaw={setMigrationJSON} setFeedback={setFeedback}/>}</Card></>
}

function MigrationPanel({ raw, setRaw, setFeedback }: { raw: string; setRaw: (value: string) => void; setFeedback: (value: { message: string; error: boolean }) => void }) {
  const [busy, setBusy] = useState('')
  const [staged, setStaged] = useState({ db_path: '', subscribes_dir: '' })
  const [uploadFile, setUploadFile] = useState<File | null>(null)
  const rememberStaged = (value: AnyRecord) => setStaged({ db_path: valueText(value.db_path), subscribes_dir: valueText(value.subscribes_dir) })
  const run = async (name: string, path: string, body?: unknown, method: 'GET' | 'POST' = 'POST') => {
    if (name === '修复客户端标识' && !window.confirm('此操作会扫描全部远程服务器，改写缺少 email 的 Xray 客户端并提交完整入站配置，可能触发 Xray 重载。确认继续？')) return
    setBusy(name)
    try {
      const value = await api<AnyRecord>(path, { method, body: method === 'GET' ? undefined : JSON.stringify(body ?? {}) })
      setRaw(JSON.stringify(value, null, 2)); setFeedback({ message: `${name} 已完成。`, error: false })
      return value
    } catch (reason) { setFeedback({ message: errorText(reason), error: true }); return null } finally { setBusy('') }
  }
  const fetchBackup = async () => {
    const url = (document.getElementById('mmw-url') as HTMLInputElement)?.value
    const username = (document.getElementById('mmw-user') as HTMLInputElement)?.value
    const password = (document.getElementById('mmw-pass') as HTMLInputElement)?.value
    const totp = (document.getElementById('mmw-totp') as HTMLInputElement)?.value
    const value = await run('抓取旧备份', '/api/admin/migrate/fetch-mmw-backup', { url, username, password, totp })
    if (value) rememberStaged(value)
  }
  const uploadBackup = async () => {
    if (!uploadFile) return
    const form = new FormData(); form.set('backup', uploadFile)
    setBusy('上传旧备份')
    try { const value = await api<AnyRecord>('/api/admin/migrate/upload-mmw-backup', { method: 'POST', body: form }); rememberStaged(value); setRaw(JSON.stringify(value, null, 2)); setFeedback({ message: '旧备份已上传并解压。', error: false }) } catch (reason) { setFeedback({ message: errorText(reason), error: true }) } finally { setBusy('') }
  }
  const importBackup = async () => {
    if (!staged.db_path) { setFeedback({ message: '请先抓取或上传旧备份。', error: true }); return }
    if (!window.confirm('将暂存的旧数据合并到当前系统？建议先下载当前备份。')) return
    await run('导入旧数据', '/api/admin/migrate/import-mmw', staged)
  }
  return <div className="settings-form extended-settings"><div className="settings-section-head"><div><h2>从旧版 MMW 导入</h2><p>先从旧主控抓取，或上传已有 ZIP；解压路径会自动带入导入步骤。</p></div></div><div className="field-row"><label><span>旧主控 URL</span><input id="mmw-url" placeholder="https://old.example.com"/></label><label><span>用户名</span><input id="mmw-user"/></label></div><div className="field-row"><label><span>密码</span><input id="mmw-pass" type="password"/></label><label><span>2FA 验证码（如需）</span><input id="mmw-totp" inputMode="numeric" autoComplete="one-time-code"/></label></div><div className="field-row"><label><span>或上传旧版备份 ZIP</span><input type="file" accept=".zip" onChange={(event) => setUploadFile(event.target.files?.[0] ?? null)}/></label><div className="aligned-action"><Button variant="secondary" disabled={Boolean(busy) || !uploadFile} onClick={() => void uploadBackup()}>上传并解压</Button></div></div><div className="action-strip"><Button variant="secondary" disabled={Boolean(busy)} onClick={() => void fetchBackup()}>抓取旧备份</Button><Button disabled={Boolean(busy) || !staged.db_path} onClick={() => void importBackup()}>导入已暂存备份</Button><Button variant="secondary" disabled={Boolean(busy)} onClick={() => void run('修复客户端标识', '/api/admin/migrate/patch-client-emails', {})}>修复客户端标识</Button><Button variant="secondary" disabled={Boolean(busy)} onClick={() => void run('扫描外部 Xray', '/api/admin/migrate/distinct-node-servers', undefined, 'GET')}>扫描外部 Xray</Button></div>{staged.db_path && <div className="info-stack"><div><strong>暂存数据库</strong><span className="mono">{staged.db_path}</span></div><div><strong>订阅目录</strong><span className="mono">{staged.subscribes_dir || '无'}</span></div></div>}<label><span>迁移结果</span><textarea className="code-area" rows={15} value={raw} onChange={(event) => setRaw(event.target.value)} spellCheck={false}/></label><div className="form-note">接管外部 Xray 会合并多片配置并改变 Agent 的运行模式，已放入“运维工作台”由管理员显式执行。</div></div>
}

export function MonitoringOperationsPage() {
  const [tab, setTab] = useState<'speed' | 'connectivity' | 'probe'>('speed')
  const [nodes, setNodes] = useState<AnyRecord[]>([]); const [servers, setServers] = useState<AnyRecord[]>([])
  const [results, setResults] = useState<AnyRecord[]>([]); const [testers, setTesters] = useState<AnyRecord[]>([])
  const [regions, setRegions] = useState<AnyRecord>({}); const [regionSource, setRegionSource] = useState('')
  const [nodeID, setNodeID] = useState(0); const [testerID, setTesterID] = useState(0); const [latencyOnly, setLatencyOnly] = useState(false)
  const [fromServer, setFromServer] = useState(0); const [toServer, setToServer] = useState(0); const [target, setTarget] = useState('1.1.1.1:443'); const [connectivity, setConnectivity] = useState<AnyRecord | null>(null)
  const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(false); const [testerName, setTesterName] = useState('家庭宽带')
  const [feedback, setFeedback] = useState({ message: '', error: false }); const [secret, setSecret] = useState('')
  const load = useCallback(async () => {
    setLoading(true)
    const [a, b, c, d, e] = await Promise.allSettled([api<AnyRecord>('/api/admin/nodes'), api<AnyRecord>('/api/admin/remote-servers'), api<AnyRecord>('/api/admin/speedtest/results?limit=100'), api<AnyRecord>('/api/admin/speedtest/testers'), api<AnyRecord>('/api/admin/probe/regions')])
    if (a.status === 'fulfilled') { const rows = list<AnyRecord>(a.value, ['nodes']); setNodes(rows); if (!nodeID && rows[0]) setNodeID(Number(rows[0].id)) }
    if (b.status === 'fulfilled') { const rows = list<AnyRecord>(b.value, ['servers']); setServers(rows); if (!fromServer && rows[0]) setFromServer(Number(rows[0].id)); if (!toServer && rows[1]) setToServer(Number(rows[1].id)) }
    if (c.status === 'fulfilled') setResults(list(c.value, ['results']))
    if (d.status === 'fulfilled') setTesters(list(d.value, ['testers']))
    if (e.status === 'fulfilled') { setRegions(e.value.regions ?? {}); setRegionSource(valueText(e.value.source)) }
    const speedErrors = [c, d].filter((item) => item.status === 'rejected') as PromiseRejectedResult[]
    if (speedErrors.length === 2) setFeedback({ message: `节点测速当前不可用：${errorText(speedErrors[0].reason)}`, error: true })
    setLoading(false)
  }, [fromServer, nodeID, toServer])
  useEffect(() => { void load() }, [])
  const runSpeed = async () => { if (!nodeID) return; setBusy(true); try { await api('/api/admin/speedtest/run', { method: 'POST', body: JSON.stringify({ node_id: nodeID, tester_id: testerID, latency_only: latencyOnly, threads: 2 }) }); setFeedback({ message: '测速任务已进入后台队列。', error: false }); window.setTimeout(() => void load(), 1500) } catch (reason) { setFeedback({ message: errorText(reason), error: true }) } finally { setBusy(false) } }
  const createTester = async () => { setBusy(true); try { const value = await api<AnyRecord>('/api/admin/speedtest/testers/create', { method: 'POST', body: JSON.stringify({ name: testerName }) }); setSecret(valueText(value.token)); setFeedback({ message: '测速端已创建，请立即保存令牌。', error: false }); await load() } catch (reason) { setFeedback({ message: errorText(reason), error: true }) } finally { setBusy(false) } }
  const revokeTester = async (id: number) => { if (!window.confirm('撤销此测速端？')) return; try { await api('/api/admin/speedtest/testers/revoke', { method: 'POST', body: JSON.stringify({ id }) }); await load() } catch (reason) { setFeedback({ message: errorText(reason), error: true }) } }
  const tcping = async () => { if (!fromServer) return; setBusy(true); try { const value = await apiResult<AnyRecord>('/api/admin/remote/tcping', { method: 'POST', body: JSON.stringify({ server_id: fromServer, targets: target.split(/[\n,]+/).map((part) => part.trim()).filter(Boolean), timeout_ms: 5000 }) }); setConnectivity(value); setFeedback({ message: value.success ? '远程拨测完成。' : value.error || '本次拨测未能完成。', error: !value.success }) } catch (reason) { setFeedback({ message: errorText(reason), error: true }) } finally { setBusy(false) } }
  const reachability = async () => { if (!fromServer || !toServer) return; setBusy(true); try { const value = await apiResult<AnyRecord>('/api/admin/remote/reachable', { method: 'POST', body: JSON.stringify({ from_server_id: fromServer, to_server_id: toServer, timeout_ms: 5000 }) }); setConnectivity(value); const conclusive = value.conclusive === true; setFeedback({ message: value.success ? '服务器之间网络可达。' : conclusive ? `链路确定不可达：${value.error || '所有已知监听端口均失败'}` : `暂时无法得出可达性结论：${value.error || '没有可确认的监听端口'}`, error: !value.success && conclusive }) } catch (reason) { setFeedback({ message: errorText(reason), error: true }) } finally { setBusy(false) } }
  return <><Header title="测速与探针" description="后台节点测速、远程路径拨测和公开探针设置" actions={<Button variant="secondary" icon="refresh" onClick={() => void load()}>刷新</Button>}/><Feedback {...feedback}/><Card className="table-card"><div className="table-toolbar"><div className="tabs"><button className={tab === 'speed' ? 'active' : ''} onClick={() => setTab('speed')}>节点测速</button><button className={tab === 'connectivity' ? 'active' : ''} onClick={() => setTab('connectivity')}>路径拨测</button><button className={tab === 'probe' ? 'active' : ''} onClick={() => setTab('probe')}>公开探针</button></div></div>{loading ? <Loading/> : tab === 'speed' ? <div className="monitor-grid"><section className="action-panel"><h2>发起测速</h2><label><span>节点</span><select value={nodeID} onChange={(event) => setNodeID(Number(event.target.value))}>{nodes.map((node) => <option key={node.id} value={node.id}>{node.node_name || node.name || `#${node.id}`}</option>)}</select></label><label><span>执行位置</span><select value={testerID} onChange={(event) => setTesterID(Number(event.target.value))}><option value="0">主控本机</option>{testers.filter((item) => item.online).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><Toggle label="只测真实连接延迟" checked={latencyOnly} onChange={setLatencyOnly}/><Button disabled={busy || !nodeID} onClick={() => void runSpeed()}>{busy ? '提交中…' : '开始后台测速'}</Button><div className="form-note">任务由后端异步执行；提交失败时不会创建结果记录。</div></section><section className="action-panel"><h2>独立测速端</h2><div className="field-row"><label><span>名称</span><input value={testerName} onChange={(event) => setTesterName(event.target.value)}/></label><div className="aligned-action"><Button variant="secondary" onClick={() => void createTester()}>创建</Button></div></div>{secret && <div className="secret-box"><code>{secret}</code><Button variant="ghost" icon="copy" onClick={() => void navigator.clipboard.writeText(secret)}>复制</Button></div>}<div className="compact-list">{testers.map((item) => <div key={item.id}><span className={`status-dot ${item.online ? 'online' : ''}`}/><div><strong>{item.name}</strong><small>{item.version || '未知版本'} · {(item.caps ?? []).join(', ') || '无能力上报'}</small></div><Button variant="danger" icon="trash" onClick={() => void revokeTester(item.id)}>撤销</Button></div>)}</div></section><section className="monitor-results"><h2>最近结果</h2>{results.length ? <div className="responsive-table"><table><thead><tr><th>节点</th><th>来源</th><th>延迟</th><th>下载</th><th>出口 IP</th><th>状态</th><th>时间</th></tr></thead><tbody>{results.map((item) => <tr key={item.id}><td>{item.node_name || `#${item.node_id}`}</td><td>{item.source}</td><td>{valueNumber(item.latency_ms).toFixed(0)} ms</td><td>{valueNumber(item.down_mbps).toFixed(1)} Mbps</td><td className="mono">{item.egress_ip || '—'}</td><td><span className={`badge ${item.status === 'ok' ? 'success' : ''}`}>{item.status}</span></td><td>{formatDate(item.created_at)}</td></tr>)}</tbody></table></div> : <Empty title="暂无测速记录" text="任务异步执行，完成后结果会保存在这里。"/>}</section></div> : tab === 'connectivity' ? <div className="split-admin"><section className="action-panel"><h2>从指定 Agent 拨测目标</h2><label><span>发起服务器</span><select value={fromServer} onChange={(event) => setFromServer(Number(event.target.value))}>{servers.map((server) => <option value={server.id} key={server.id}>{server.name}</option>)}</select></label><label><span>目标（逗号或换行，最多 8 个）</span><textarea rows={5} value={target} onChange={(event) => setTarget(event.target.value)}/></label><Button disabled={busy || !fromServer} onClick={() => void tcping()}>开始远程 TCP 拨测</Button></section><section className="action-panel"><h2>服务器之间可达性</h2><div className="field-row"><label><span>来源</span><select value={fromServer} onChange={(event) => setFromServer(Number(event.target.value))}>{servers.map((server) => <option value={server.id} key={server.id}>{server.name}</option>)}</select></label><label><span>目标</span><select value={toServer} onChange={(event) => setToServer(Number(event.target.value))}>{servers.map((server) => <option value={server.id} key={server.id}>{server.name}</option>)}</select></label></div><Button disabled={busy || !fromServer || !toServer || fromServer === toServer} onClick={() => void reachability()}>预检链路</Button>{connectivity && <pre className="progress-log">{JSON.stringify(connectivity, null, 2)}</pre>}</section></div> : <ProbeSettingsPanel servers={servers} regions={regions} regionSource={regionSource}/>}</Card></>
}

