export function OperationsWorkbenchPage() {
  const groups = useMemo(() => Array.from(new Set(operationCatalog.map((item) => item.group))), [])
  const [group, setGroup] = useState(groups[0]); const [query, setQuery] = useState(''); const [selected, setSelected] = useState<OperationSpec>(operationCatalog[0])
  const [path, setPath] = useState(selected.path); const [body, setBody] = useState(JSON.stringify(selected.body ?? {}, null, 2)); const [result, setResult] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState('')
  const filtered = operationCatalog.filter((item) => item.group === group && `${item.title} ${item.description} ${item.path}`.toLowerCase().includes(query.toLowerCase()))
  const choose = (item: OperationSpec) => { setSelected(item); setPath(item.path); setBody(JSON.stringify(item.body ?? {}, null, 2)); setResult(''); setError('') }
  const run = async () => {
    if (selected.dangerous && !window.confirm(`确认执行“${selected.title}”？\n\n${selected.description}`)) return
    setBusy(true); setError(''); setResult('')
    try {
      let parsed: unknown = undefined
      if (selected.method !== 'GET') parsed = body.trim() ? JSON.parse(body) : {}
      const value = await api<unknown>(path, { method: selected.method, body: selected.method === 'GET' ? undefined : JSON.stringify(parsed) })
      setResult(typeof value === 'string' ? value : JSON.stringify(value, null, 2))
    } catch (reason) { setError(reason instanceof SyntaxError ? '请求体必须是有效 JSON。' : errorText(reason)) } finally { setBusy(false) }
  }
  return <><Header title="运维工作台" description="覆盖低频与高风险后端能力；每次调用都明确展示路径、请求和响应"/><div className="workbench"><Card className="workbench-sidebar"><label className="search"><Icon name="activity"/><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="搜索操作或路径"/></label><div className="workbench-groups">{groups.map((item) => <button key={item} className={group === item ? 'active' : ''} onClick={() => { setGroup(item); const first = operationCatalog.find((operation) => operation.group === item); if (first) choose(first) }}>{item}<span>{operationCatalog.filter((operation) => operation.group === item).length}</span></button>)}</div></Card><Card className="workbench-list"><h2>{group}</h2>{filtered.map((item) => <button key={`${item.method}-${item.path}-${item.title}`} className={selected === item ? 'active' : ''} onClick={() => choose(item)}><span className={`method ${item.method.toLowerCase()}`}>{item.method}</span><div><strong>{item.title}</strong><small>{item.description}</small></div>{item.dangerous && <span className="danger-mark">!</span>}</button>)}</Card><Card className="workbench-editor"><div className="card-head"><div><span className={`method ${selected.method.toLowerCase()}`}>{selected.method}</span><h2>{selected.title}</h2><p>{selected.description}</p></div></div><label><span>请求路径</span><input className="mono" value={path} onChange={(event) => setPath(event.target.value)}/></label>{selected.method !== 'GET' && <label><span>JSON 请求体</span><textarea className="code-area" rows={13} value={body} onChange={(event) => setBody(event.target.value)} spellCheck={false}/></label>}{selected.dangerous && <div className="danger-note"><Icon name="shield"/><span>这项操作会改变远程或持久化状态，执行前会再次确认。</span></div>}<Feedback message={error} error/><Button disabled={busy} onClick={() => void run()}>{busy ? '执行中…' : '执行请求'}</Button>{result && <div className="result-panel"><div><strong>响应</strong><Button variant="ghost" icon="copy" onClick={() => void navigator.clipboard.writeText(result)}>复制</Button></div><pre>{result}</pre></div>}</Card></div></>
}
